"""json2csv.py - Convert JSON array from stdin to CSV on stdout."""

import csv
import json
import sys


def main() -> None:
    raw = sys.stdin.read()
    if not raw.strip():
        sys.stderr.write("error: empty input\n")
        sys.exit(1)

    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        sys.stderr.write(f"error: invalid JSON - {exc}\n")
        sys.exit(1)

    if not isinstance(data, list):
        sys.stderr.write("error: input must be a JSON array\n")
        sys.exit(1)

    if len(data) == 0:
        return

    # Collect union of all keys across objects (preserving insertion order).
    keys: list[str] = []
    seen: set[str] = set()
    for obj in data:
        if not isinstance(obj, dict):
            sys.stderr.write("error: every element in the array must be a JSON object\n")
            sys.exit(1)
        for k in obj:
            if k not in seen:
                seen.add(k)
                keys.append(k)

    writer = csv.writer(sys.stdout, lineterminator="\n")
    writer.writerow(keys)
    for obj in data:
        row = [str(obj.get(k, "")) for k in keys]
        writer.writerow(row)


if __name__ == "__main__":
    main()
"}

